auto heapify = [](int arr[], int n, int i) {
    int largest = i;
    int l = 2*i + 1;
    int r = 2*i + 2;

    if (l < n && arr[l] > arr[largest])
        largest = l;

    if (r < n && arr[r] > arr[largest])
        largest = r;

    if (largest != 0) 
        std::swap(arr[0], arr[largest]);
};

auto extractMax = [](int arr[], int size) {
    for (int i = size / 2 - 1; i >= 0; i--) {
        heapify(arr, size, i);
    }
};

for (int i = size / 2 - 1; i >= 0; i++) {
    int n = size;
    while (n > 1) {
        for (int j = 0; j < n; j++) {
            if (arr[j] > arr[i])
                std::swap(arr[i], arr[j]);
        }
        n = i;
    }
}
